/**
 * Country boundaries - Natural Earth 1:50m admin-0, simplified and packed.
 * Generated by tools/build-shapes.ps1 - do not edit by hand.
 *
 * Each ring is "ISO3~<varints>": zig-zag deltas of lon/lat at 0.01 deg,
 * 5 bits per character over a JS-safe alphabet. LAND is drawn at full
 * detail, LAND_LOW when the view is zoomed out.
 */

const SHAPE_ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+-';

function decodeShapes(blob) {
  const idx = new Int8Array(128);
  for (let i = 0; i < SHAPE_ALPHA.length; i++) idx[SHAPE_ALPHA.charCodeAt(i)] = i;
  return blob.split('|').map(chunk => {
    const iso = chunk.slice(0, 3);
    const s = chunk, ring = [];
    let i = 4, lon = 0, lat = 0;
    while (i < s.length) {
      let r = 0, sh = 0, b;
      do { b = idx[s.charCodeAt(i++)]; r |= (b & 31) << sh; sh += 5; } while (b >= 32);
      lon += (r & 1) ? ~(r >> 1) : (r >> 1);
      r = 0; sh = 0;
      do { b = idx[s.charCodeAt(i++)]; r |= (b & 31) << sh; sh += 5; } while (b >= 32);
      lat += (r & 1) ? ~(r >> 1) : (r >> 1);
      ring.push([lon / 100, lat / 100]);
    }
    return { iso, ring };
  });
}

